-- No model/provider calls. Keep every production trigger enabled; pg_net
-- enqueue rows and all fixtures are uncommitted and disappear at ROLLBACK.
BEGIN;
CREATE TEMP TABLE planning_checks(name text PRIMARY KEY);
CREATE FUNCTION pg_temp.planning_assert(name text,value boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'mission planning assertion failed: %',name; END IF; INSERT INTO planning_checks VALUES(name); END $$;
CREATE FUNCTION pg_temp.planning_reject(name text,statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE rejected boolean:=false; BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF position(expected IN SQLERRM)=0 THEN RAISE EXCEPTION 'unexpected rejection for %: %',name,SQLERRM; END IF; rejected:=true; END; IF NOT rejected THEN RAISE EXCEPTION 'missing rejection: %',name; END IF; INSERT INTO planning_checks VALUES(name); END $$;
CREATE TEMP TABLE planning_fixtures(name text PRIMARY KEY,customer_id uuid,mission_id uuid,run_id uuid,audit_id uuid,question_id uuid,client_step uuid,active_step uuid,completed_step uuid,obsolete_step uuid);
CREATE FUNCTION pg_temp.planning_fixture(label text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE c uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); r uuid; q uuid:=gen_random_uuid(); client uuid:=gen_random_uuid(); active uuid:=gen_random_uuid(); done uuid:=gen_random_uuid(); old uuid:=gen_random_uuid();
BEGIN
 INSERT INTO public.email_customers(id,display_name,google_drive_folder_status) VALUES(c,'Planning rollback fixture','excluded');
 INSERT INTO public.sandy_tasks(id,customer_id,title,details,status,source_kind,metadata) VALUES(m,c,'Reversible mission plan','Actual saved customer context; no model or provider execution.','waiting','integration_test','{"sandy_mission":true,"execution_state":"planning"}');
 SELECT id INTO r FROM public.sandy_mission_runs WHERE mission_task_id=m AND customer_id=c AND stage='plan';
 IF r IS NULL THEN RAISE EXCEPTION 'original mission trigger did not create actual plan run'; END IF;
 INSERT INTO public.sandy_mission_questions(id,customer_id,mission_task_id,question,question_key,status,answer) VALUES(q,c,m,'What is the confirmed delivery date?','confirmed delivery date','answered','30 November');
 INSERT INTO public.sandy_tasks(id,customer_id,parent_task_id,title,status,source_kind,metadata) VALUES
 (client,c,m,'Keep client approval task','todo','integration_test','{"stage":"planned","assigned_to":"client","mission_run_id":"old","approval_required":true}'),
 (active,c,m,'Keep active Sandy work','in_progress','integration_test','{"stage":"planned","assigned_to":"sandy","mission_run_id":"old","approval_required":false}'),
 (done,c,m,'Keep completed work','completed','integration_test','{"stage":"planned","assigned_to":"sandy","mission_run_id":"old","approval_required":false}'),
 (old,c,m,'Supersede only unstarted Sandy work','todo','integration_test','{"stage":"planned","assigned_to":"sandy","mission_run_id":"old","approval_required":false}');
 INSERT INTO planning_fixtures VALUES(label,c,m,r,NULL,q,client,active,done,old);
END $$;
SELECT pg_temp.planning_fixture('success'); SELECT pg_temp.planning_fixture('unavailable'); SELECT pg_temp.planning_fixture('changed'); SELECT pg_temp.planning_fixture('unknown'); SELECT pg_temp.planning_fixture('foreign');
SELECT pg_temp.planning_assert('both private contracts stay closed cost-sensitive mutations',count(*)=2 AND bool_and(is_mutation AND NOT api_exposed AND NOT ui_exposed AND NOT ai_exposed AND NOT verified AND (error_contract->>'consumes_model_resources')::boolean AND (error_contract->>'sensitive')::boolean AND handler='internal:'||operation||'@1.0.0' AND input_schema->'properties'='{}'::jsonb AND error_contract->'auth_user_id'='null'::jsonb)) FROM public.sandy_operation_registry WHERE operation IN('agent.missions.plan.prepare','agent.missions.questions.review');
SELECT pg_temp.planning_assert('receipt RLS and service-only functions', (SELECT relrowsecurity FROM pg_class WHERE oid='public.sandy_mission_planning_audit'::regclass) AND NOT has_table_privilege('authenticated','public.sandy_mission_planning_audit','SELECT') AND NOT has_table_privilege('service_role','public.sandy_mission_planning_audit','INSERT') AND NOT has_table_privilege('service_role','public.sandy_mission_planning_audit','UPDATE') AND has_function_privilege('service_role','public.sandy_prepare_mission_plan(uuid,uuid,uuid,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.sandy_record_mission_question_review(uuid,text,jsonb,text,text)','EXECUTE'));
SELECT pg_temp.planning_assert('all production triggers stay enabled; fixture provenance avoids analysis enqueue',NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.sandy_tasks'::regclass AND NOT tgisinternal AND tgenabled='D') AND NOT EXISTS(SELECT 1 FROM public.sandy_task_analysis_queue WHERE customer_id IN(SELECT customer_id FROM planning_fixtures)));
SELECT pg_temp.planning_reject('wrong source cannot claim',format('SELECT public.sandy_prepare_mission_plan(%L,%L,%L,%L)',run_id,customer_id,mission_id,repeat('f',64)),'mission_plan_admission_scope_mismatch') FROM planning_fixtures WHERE name='success';
SELECT pg_temp.planning_reject('actual tenant required',format('SELECT public.sandy_prepare_mission_plan(%L,%L,%L,%L)',run_id,gen_random_uuid(),mission_id,'f4a852845706e11bec633808c3374501b17989923b48c7662bb0e1df789a46d1'),'mission_actual_plan_run_scope_required') FROM planning_fixtures WHERE name='success';
UPDATE public.sandy_mission_questions SET customer_id=(SELECT customer_id FROM planning_fixtures WHERE name='success') WHERE id=(SELECT question_id FROM planning_fixtures WHERE name='foreign');
SELECT pg_temp.planning_reject('legacy noncomposite question FK is not tenant authority',format('SELECT public.sandy_prepare_mission_plan(%L,%L,%L,%L)',run_id,customer_id,mission_id,'f4a852845706e11bec633808c3374501b17989923b48c7662bb0e1df789a46d1'),'mission_plan_question_file_tenant_mismatch') FROM planning_fixtures WHERE name='foreign';
UPDATE planning_fixtures f SET audit_id=(public.sandy_prepare_mission_plan(run_id,customer_id,mission_id,'f4a852845706e11bec633808c3374501b17989923b48c7662bb0e1df789a46d1')->>'id')::uuid WHERE name<>'foreign';
SELECT pg_temp.planning_assert('planner sees actual five-key tool readiness without execution claims',jsonb_array_length(a.context->'availableTools')=5 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.context->'availableTools')t WHERE NOT EXISTS(SELECT 1 FROM public.sandy_operational_tool_registry v WHERE v.tool_key=t->>'tool_key' AND v.readiness=t->>'readiness' AND v.name=t->>'name' AND v.policy=t->>'policy'))) FROM planning_fixtures f JOIN public.sandy_mission_planning_audit a ON a.id=f.audit_id WHERE f.name='success';
SELECT pg_temp.planning_assert('actual queue claimed once with task and answered context',a.state='started' AND j.state='running' AND a.auth_user_id IS NULL AND a.context->'answered'->0->>'answer'='30 November' AND jsonb_array_length(a.context->'steps')=4 AND a.customer_id=f.customer_id) FROM planning_fixtures f JOIN public.sandy_mission_planning_audit a ON a.id=f.audit_id JOIN public.sandy_mission_runs j ON j.id=f.run_id WHERE f.name='success';
SELECT pg_temp.planning_reject('same run cannot redispatch',format('SELECT public.sandy_prepare_mission_plan(%L,%L,%L,%L)',run_id,customer_id,mission_id,'f4a852845706e11bec633808c3374501b17989923b48c7662bb0e1df789a46d1'),'mission_plan_one_use_claim_exists') FROM planning_fixtures WHERE name='unknown';
CREATE FUNCTION pg_temp.planning_milestones(f planning_fixtures) RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_agg(jsonb_build_object('customer_id',f.customer_id,'parent_task_id',f.mission_id,'title','Rollback draft milestone '||i,'details','Pending client plan review.','status',CASE WHEN i=2 THEN 'waiting' ELSE 'todo' END,'priority','normal','metadata',jsonb_build_object('sandy_mission_step',true,'assigned_to',CASE WHEN i=2 THEN 'client' ELSE 'sandy' END,'approval_required',i=2,'stage','planned','mission_run_id',f.run_id,'plan_index',i,'suggested_tool','none','tool_execution_state','not_executed','depends_on','[]'::jsonb)) ORDER BY i) FROM generate_series(1,3)i $$;
CREATE FUNCTION pg_temp.planning_record(f planning_fixtures) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.sandy_record_mission_plan_proposal(f.audit_id,'{"summary":"Reversible plan pending customer review","milestones":[{},{},{}],"success_criteria":["Editable draft"],"plan_changes":["Preserve client and active work"],"decision_tree":[{"condition":"Client approves","on_yes":"Prepare internal draft","on_no":"Revise draft"}]}',pg_temp.planning_milestones(f)::text,'[{"question":"Who has mandatory approval authority?","question_key":"mandatory approval authority"},{"question":"What is the new required safety constraint?","question_key":"new required safety constraint"}]','resp_rollback_fixture_not_provider_test',repeat('a',64)) $$;
SELECT pg_temp.planning_reject('no bare provider receipt assertion',format('SELECT public.sandy_record_mission_plan_proposal(%L,%L,%L,%L,NULL,NULL)',f.audit_id,'{}',pg_temp.planning_milestones(f)::text,'[]'),'mission_actual_plan_proposal_receipt_required') FROM planning_fixtures f WHERE name='success';
SELECT pg_temp.planning_assert('actual proposal is stored before reviewer admission',bool_and((pg_temp.planning_record(f)->>'review_required')::boolean)) FROM planning_fixtures f WHERE name IN('success','unavailable','changed');
SELECT pg_temp.planning_assert('recorded reviewer binds actual answers and candidates',a.state='proposal_received' AND a.review_state='started' AND jsonb_array_length(a.candidates)=2 AND a.provider_response_id='resp_rollback_fixture_not_provider_test') FROM planning_fixtures f JOIN public.sandy_mission_planning_audit a ON a.id=f.audit_id WHERE f.name='success';
SELECT pg_temp.planning_reject('stored proposal cannot be replaced before another review',format('SELECT pg_temp.planning_record(f) FROM planning_fixtures f WHERE name=%L','success'),'mission_actual_plan_proposal_receipt_required');
SELECT pg_temp.planning_reject('review must finish before plan writes',format('SELECT public.sandy_finish_mission_plan(%L,false)',audit_id),'mission_complete_plan_proposal_review_required') FROM planning_fixtures WHERE name='success';
SELECT pg_temp.planning_reject('reviewed requires real response provenance',format('SELECT public.sandy_record_mission_question_review(%L,''reviewed'',''[0]'',NULL,NULL)',audit_id),'mission_actual_question_review_receipt_required') FROM planning_fixtures WHERE name='success';
SELECT pg_temp.planning_reject('review cannot select an out-of-range candidate',format('SELECT public.sandy_record_mission_question_review(%L,''reviewed'',''[7]'',''resp_review'',%L)',audit_id,repeat('b',64)),'mission_review_keep_indexes_invalid') FROM planning_fixtures WHERE name='success';
SELECT pg_temp.planning_assert('valid review retains only actual selected candidate',(public.sandy_record_mission_question_review(audit_id,'reviewed','[1]','resp_rollback_review_not_provider_test',repeat('b',64))->>'ok')::boolean) FROM planning_fixtures WHERE name='success';
SELECT pg_temp.planning_assert('unknown review is explicit and cannot remove questions',bool_and((public.sandy_record_mission_question_review(audit_id,'review_exception',NULL,NULL,NULL)->>'ok')::boolean)) FROM planning_fixtures WHERE name IN('unavailable','changed');
SELECT pg_temp.planning_reject('finished reviewer cannot consume model again',format('SELECT public.sandy_record_mission_question_review(%L,''reviewed'',''[0]'',''resp_repeat'',%L)',audit_id,repeat('b',64)),'mission_recorded_question_review_claim_required') FROM planning_fixtures WHERE name='success';
UPDATE public.sandy_mission_questions SET answer='The client changed this answer after model dispatch' WHERE id=(SELECT question_id FROM planning_fixtures WHERE name='changed');
SELECT pg_temp.planning_reject('changed client answer cannot be overwritten by stale proposal',format('SELECT public.sandy_finish_mission_plan(%L,false)',audit_id),'mission_plan_context_changed_reconcile') FROM planning_fixtures WHERE name='changed';
SELECT pg_temp.planning_assert('context rejection leaves plan writes atomic',NOT EXISTS(SELECT 1 FROM public.sandy_tasks WHERE metadata->>'mission_run_id'=f.run_id::text) AND NOT EXISTS(SELECT 1 FROM public.sandy_mission_decisions WHERE run_id=f.run_id)) FROM planning_fixtures f WHERE f.name='changed';
SELECT pg_temp.planning_assert('unknown primary remains explicit with no automatic retry',(public.sandy_finish_mission_plan(audit_id,true)->>'reconciliation_required')::boolean) FROM planning_fixtures WHERE name='unknown';
CREATE TEMP TABLE planning_cross_run(id uuid);
WITH added AS(INSERT INTO public.sandy_mission_runs(mission_task_id,customer_id,stage,state,run_key) SELECT mission_id,customer_id,'plan','queued','rollback-new-plan:'||gen_random_uuid() FROM planning_fixtures WHERE name='unknown' RETURNING id) INSERT INTO planning_cross_run SELECT id FROM added;
SELECT pg_temp.planning_reject('another run ID cannot repeat unknown logical mission',format('SELECT public.sandy_prepare_mission_plan(%L,%L,%L,%L)',c.id,f.customer_id,f.mission_id,'f4a852845706e11bec633808c3374501b17989923b48c7662bb0e1df789a46d1'),'mission_plan_outcome_requires_reconciliation') FROM planning_cross_run c CROSS JOIN planning_fixtures f WHERE f.name='unknown';
SELECT pg_temp.planning_assert('atomic reviewed completion returns correct record counts',(public.sandy_finish_mission_plan(audit_id,false)->>'new_questions')::integer=1) FROM planning_fixtures WHERE name='success';
SELECT pg_temp.planning_assert('unavailable reviewer preserves both questions',(public.sandy_finish_mission_plan(audit_id,false)->>'new_questions')::integer=2) FROM planning_fixtures WHERE name='unavailable';
SELECT pg_temp.planning_assert('client active completed tasks preserved; only old unstarted Sandy task superseded',(SELECT status='todo' AND metadata->>'assigned_to'='client' FROM public.sandy_tasks WHERE id=f.client_step) AND (SELECT status='in_progress' FROM public.sandy_tasks WHERE id=f.active_step) AND (SELECT status='completed' FROM public.sandy_tasks WHERE id=f.completed_step) AND (SELECT status='cancelled' AND metadata->>'superseded_by_run_id'=f.run_id::text FROM public.sandy_tasks WHERE id=f.obsolete_step)) FROM planning_fixtures f WHERE name='success';
SELECT pg_temp.planning_assert('actual saved plan is pending client input with no execution proof',a.state='succeeded' AND j.state='completed' AND j.result->>'external_actions_performed'='0' AND m.metadata->>'execution_state'='awaiting_client_information' AND (SELECT count(*) FROM public.sandy_tasks WHERE metadata->>'mission_run_id'=f.run_id::text)=3 AND NOT EXISTS(SELECT 1 FROM public.sandy_tasks WHERE metadata->>'mission_run_id'=f.run_id::text AND metadata->>'tool_execution_state'<>'not_executed') AND (SELECT count(*) FROM public.sandy_mission_decisions WHERE run_id=f.run_id)=1) FROM planning_fixtures f JOIN public.sandy_mission_planning_audit a ON a.id=f.audit_id JOIN public.sandy_mission_runs j ON j.id=f.run_id JOIN public.sandy_tasks m ON m.id=f.mission_id WHERE f.name='success';
SELECT pg_temp.planning_assert('answered question is authoritative and not duplicated',(SELECT count(*) FROM public.sandy_mission_questions WHERE mission_task_id=f.mission_id AND status='answered' AND answer='30 November')=1 AND (SELECT count(*) FROM public.sandy_mission_questions WHERE mission_task_id=f.mission_id AND question_key='mandatory approval authority')=0 AND (SELECT count(*) FROM public.sandy_mission_questions WHERE mission_task_id=f.mission_id AND question_key='new required safety constraint')=1) FROM planning_fixtures f WHERE name='success';
SELECT pg_temp.planning_reject('completed finalizer cannot duplicate milestones questions decisions',format('SELECT public.sandy_finish_mission_plan(%L,false)',audit_id),'mission_plan_finish_claim_required') FROM planning_fixtures WHERE name='success';
SELECT pg_temp.planning_assert('task analysis dispatch remains transactional outbox insert',(SELECT l.lanname='plpgsql' AND position('insert into net.http_request_queue' IN p.prosrc)>0 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid='net.http_post(text,jsonb,jsonb,jsonb,integer)'::regprocedure));
SELECT jsonb_build_object('status','pass','component_checks',count(*),'real_provider_calls',0,'real_model_calls',0,'real_customer_execution_tested',false,'all_production_triggers_enabled',NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.sandy_tasks'::regclass AND NOT tgisinternal AND tgenabled='D'),'fixture_customer_ids',(SELECT jsonb_agg(customer_id) FROM planning_fixtures),'uncommitted_http_outbox_ids',(SELECT coalesce(jsonb_agg(id),'[]') FROM net.http_request_queue WHERE pg_xact_status(xmin::text::xid8)='in progress'),'all_changes_rolled_back',true) AS mission_planning_evidence FROM planning_checks;
ROLLBACK;
